// Package api: router.go registers the OpenAPI-derived routes onto a Fiber app,
// with the path-aware audit gate (per-route RequirePerm) layered on top.
//
// All public routes are defined in api/openapi.yaml and code-generated by
// oapi-codegen into apigen.RegisterHandlers. This file is the single wiring
// point: program/ builds a *Server (api.NewServer) + a PolicyResolver and
// passes them to RegisterRoutes after the middleware stack is in place.
//
// Per-route permission enforcement for the audit endpoints is provided by
// AuditGate — a path-aware middleware that runs RequirePerm for /api/v1/audit*
// paths only. apigen.RegisterHandlers does not natively support per-route
// middleware for Fiber (its FiberServerOptions.Middlewares is global), so the
// gate pattern is the cleanest path that does not require duplicating
// apigen's generated routing table by hand.
package api

import (
	"strings"

	"github.com/avestura/lahijan/api/gen/go"
	"github.com/avestura/lahijan/internal/app/lahijan/api/middleware"
	"github.com/avestura/lahijan/internal/app/lahijan/auth/rbac"
	"github.com/gofiber/fiber/v2"
)

// RegisterRoutes wires the given server onto app with the audit gate applied
// to the audit routes. The handlers live in server.go / auth_handlers.go /
// audit_handlers.go; the routing table is generated by oapi-codegen (apigen).
//
// A catch-all fallback at the end guarantees that requests to undefined paths
// return the standard error envelope (404 not_found) rather than Fiber's
// default plain-text body.
func RegisterRoutes(app *fiber.App, server *Server, policy middleware.PolicyResolver) {
	opts := apigen.FiberServerOptions{}
	if policy != nil {
		opts.Middlewares = []apigen.MiddlewareFunc{AuditGate(policy)}
	}
	apigen.RegisterHandlersWithOptions(app, server, opts)
	// Catch-all: only fires when no registered route matched.
	app.Use(NotFound)
}

// AuditGate returns a path-aware middleware that runs RequirePerm for the
// privileged endpoints and bypasses every other path. It exists because:
//
//   - apigen.FiberServerOptions.Middlewares is a flat list (no per-route map),
//     so any middleware we add runs for every route.
//   - Registering routes manually would conflict with apigen's
//     registration (Fiber panics on duplicate routes).
//
// The gate inspects c.Path() + c.Method() and dispatches to the right
// RequirePerm slug:
//
//	/api/v1/audit/export           -> audit.export
//	/api/v1/audit/{id}             -> audit.read
//	/api/v1/audit                  -> audit.read
//	/api/v1/admin/jobs/*/retry     -> platform.jobs.retry
//	/api/v1/admin/jobs/*/cancel    -> platform.jobs.cancel
//	/api/v1/admin/jobs/{id}        -> platform.jobs.read
//	/api/v1/admin/jobs             -> platform.jobs.read
//	/api/v1/admin/plugins/upload   -> plugins.install
//	/api/v1/admin/plugins/*/enable  -> plugins.install
//	/api/v1/admin/plugins/*/disable -> plugins.install
//	/api/v1/admin/plugins/*/permissions/*/* -> plugins.permission.approve
//	/api/v1/admin/plugins/install/*  -> plugins.install     (WS-10c marketplace)
//	/api/v1/admin/plugins/upgrade/*  -> plugins.install     (WS-10c marketplace)
//	/api/v1/admin/marketplace        -> plugins.read        (WS-10c marketplace)
//	/api/v1/admin/marketplace/*      -> plugins.read        (WS-10c marketplace)
//	/api/v1/admin/plugins/{id}     -> plugins.read  (GET) / plugins.uninstall (DELETE)
//	/api/v1/admin/plugins          -> plugins.read
//	/api/v1/compute/instances POST                    -> compute.instance.create
//	/api/v1/compute/instances GET                     -> compute.instance.read
//	/api/v1/compute/instances/{id} GET / PATCH        -> compute.instance.read / .update
//	/api/v1/compute/instances/{id} DELETE             -> compute.instance.delete
//	/api/v1/compute/instances/{id}/{start|stop|...}   -> compute.instance.<action>
//	/api/v1/compute/instances/{id}/exec POST          -> compute.instance.start
//	                                                          (exec needs a running instance)
//	/api/v1/compute/instances/{id}/vnc GET            -> compute.instance.console.vnc
//	                                                          (WS-24 noVNC graphical console)
//	/api/v1/compute/images GET                        -> compute.image.read
//	/api/v1/compute/images POST                       -> compute.instance.create
//	                                                          (custom upload is create-adjacent)
//	/api/v1/compute/images/{id} GET                   -> compute.image.read
//	/api/v1/compute/images/{id} DELETE                -> compute.instance.delete
//	/api/v1/compute/profiles GET / POST               -> compute.profile.read / .apply
//	/api/v1/compute/profiles/{id} GET                 -> compute.profile.read
//	/api/v1/compute/profiles/{id} DELETE              -> compute.profile.apply
//	/api/v1/compute/networks GET / POST               -> compute.network.read / .create
//	/api/v1/compute/networks/{id} GET                 -> compute.network.read
//	/api/v1/compute/networks/{id} DELETE              -> compute.network.create
//	/api/v1/compute/storage GET / POST                -> compute.storage_pool.read
//	/api/v1/compute/storage/{id} GET                  -> compute.storage_pool.read
//	/api/v1/compute/storage/{id} DELETE               -> compute.storage_pool.read
//
//	/api/v1/dns/zones GET / POST                      -> dns.zone.read / .create
//	/api/v1/dns/zones/{id} GET / PATCH                -> dns.zone.read / .update
//	/api/v1/dns/zones/{id} DELETE                     -> dns.zone.delete
//	/api/v1/dns/zones/{id}/records GET / POST         -> dns.record.read / .create
//	/api/v1/dns/zones/{id}/records/{id} GET / PATCH   -> dns.record.read / .update
//	/api/v1/dns/zones/{id}/records/{id} DELETE        -> dns.record.delete
//	/api/v1/dns/zones/{id}/dnssec/{enable|disable}    -> dns.zone.update
//	/api/v1/dns/zones/{id}/apply-template POST        -> dns.zone.update
//	/api/v1/dns/templates GET                         -> dns.zone.read
//
//	/api/v1/storage/buckets GET / POST                -> s3.bucket.read / .create
//	/api/v1/storage/buckets/{id} GET / PATCH          -> s3.bucket.read / .update
//	/api/v1/storage/buckets/{id} DELETE               -> s3.bucket.delete
//	/api/v1/storage/buckets/{id}/credentials GET / POST
//	                                                  -> s3.credentials.create / .create
//	                                                      (list reuses s3.bucket.read)
//	/api/v1/storage/buckets/{id}/credentials/{id} DELETE
//	                                                  -> s3.credentials.revoke
//	/api/v1/storage/buckets/{id}/presign POST         -> s3.object.read (GET) /
//	                                                      s3.object.read (PUT; upload needs read perm too)
//	/api/v1/storage/buckets/{id}/quota POST           -> s3.bucket.update
//	/api/v1/storage/buckets/{id}/usage GET            -> s3.bucket.read
//
//	/api/v1/me/balance GET                            -> billing.balance.read
//	/api/v1/me/usage GET                              -> billing.balance.read
//	/api/v1/me/ledger GET                             -> billing.ledger.read
//	/api/v1/me/receipts GET / POST                    -> billing.receipt.read / .create
//	/api/v1/me/receipts/{id} GET                      -> billing.receipt.read
//	/api/v1/me/receipts/{id}.pdf GET                  -> billing.receipt.read
//	/api/v1/admin/billing/prices GET / POST           -> billing.price_catalog.read / .update
//	/api/v1/admin/users/{id}/topup POST               -> billing.balance.adjust
//	/api/v1/admin/users/{id}/refund POST              -> billing.balance.adjust
//	/api/v1/admin/users/{id}/ledger GET               -> billing.ledger.read
//	/api/v1/admin/users/{id}/balance GET              -> billing.balance.read
//	/api/v1/admin/users/{id}/balance POST             -> billing.balance.adjust
//
// Everything else: c.Next() (no enforcement; routes that need it must add
// their own per-route RequirePerm or be gated through this same function as
// the privileged surface grows).
func AuditGate(policy middleware.PolicyResolver) apigen.MiddlewareFunc {
	return func(c *fiber.Ctx) error {
		path := c.Path()
		method := c.Method()
		switch {
		// WS-08: audit log endpoints.
		case path == "/api/v1/audit/export":
			return middleware.RequirePerm(policy, rbac.PermAuditExport)(c)
		case path == "/api/v1/audit":
			return middleware.RequirePerm(policy, rbac.PermAuditRead)(c)
		case strings.HasPrefix(path, "/api/v1/audit/"):
			return middleware.RequirePerm(policy, rbac.PermAuditRead)(c)

		// WS-09: admin job system endpoints. These are platform-only; only
		// the platform.admin role (auto-bypass in the evaluator) holds the
		// platform.jobs.* permissions, so tenant-scoped admins cannot reach
		// another tenant's jobs.
		case strings.HasPrefix(path, "/api/v1/admin/jobs/") && strings.HasSuffix(path, "/retry"):
			return middleware.RequirePerm(policy, rbac.PermPlatformJobsRetry)(c)
		case strings.HasPrefix(path, "/api/v1/admin/jobs/") && strings.HasSuffix(path, "/cancel"):
			return middleware.RequirePerm(policy, rbac.PermPlatformJobsCancel)(c)
		case path == "/api/v1/admin/jobs":
			return middleware.RequirePerm(policy, rbac.PermPlatformJobsRead)(c)
		case strings.HasPrefix(path, "/api/v1/admin/jobs/"):
			return middleware.RequirePerm(policy, rbac.PermPlatformJobsRead)(c)

		// WS-10c: marketplace endpoints. The browse paths (GET
		// /marketplace, GET /marketplace/{name}) require plugins.read
		// so tenant admins can see what's available. The install +
		// upgrade paths require plugins.install because they persist
		// rows + emit audit events.
		case path == "/api/v1/admin/marketplace":
			return middleware.RequirePerm(policy, rbac.PermPluginsRead)(c)
		case strings.HasPrefix(path, "/api/v1/admin/marketplace/"):
			return middleware.RequirePerm(policy, rbac.PermPluginsRead)(c)
		case strings.HasPrefix(path, "/api/v1/admin/plugins/install/"):
			return middleware.RequirePerm(policy, rbac.PermPluginsInstall)(c)
		case strings.HasPrefix(path, "/api/v1/admin/plugins/upgrade/"):
			return middleware.RequirePerm(policy, rbac.PermPluginsInstall)(c)

		// WS-10a: admin plugin endpoints. The WS-10a DoD requires "only
		// platform.admin can hit the admin plugin API". Concretely this
		// means every /admin/plugins/* path MUST require plugins.install
		// (or plugins.uninstall / plugins.permission.approve) — those
		// slugs are NOT in the tenant.member / tenant.viewer bundles, so
		// only tenant.admin and platform.admin reach the handlers. The
		// tenant-scoped plugins.read permission (which viewer+member hold)
		// is reserved for a future /api/v1/plugins tenant-scoped surface
		// (WS-21); the admin API is separate.
		case path == "/api/v1/admin/plugins/upload" && c.Method() == "POST":
			return middleware.RequirePerm(policy, rbac.PermPluginsInstall)(c)
		case strings.HasPrefix(path, "/api/v1/admin/plugins/") && strings.HasSuffix(path, "/enable"):
			return middleware.RequirePerm(policy, rbac.PermPluginsInstall)(c)
		case strings.HasPrefix(path, "/api/v1/admin/plugins/") && strings.HasSuffix(path, "/disable"):
			return middleware.RequirePerm(policy, rbac.PermPluginsInstall)(c)
		case strings.HasPrefix(path, "/api/v1/admin/plugins/") && strings.Contains(path, "/permissions/"):
			return middleware.RequirePerm(policy, rbac.PermPluginsPermissionApprove)(c)
		case strings.HasPrefix(path, "/api/v1/admin/plugins/") && c.Method() == "DELETE":
			return middleware.RequirePerm(policy, rbac.PermPluginsUninstall)(c)
		case path == "/api/v1/admin/plugins":
			return middleware.RequirePerm(policy, rbac.PermPluginsInstall)(c)
		case strings.HasPrefix(path, "/api/v1/admin/plugins/"):
			return middleware.RequirePerm(policy, rbac.PermPluginsInstall)(c)

		// WS-14: compute module endpoints. Every /api/v1/compute/* path
		// is gated; the slug maps 1:1 with the rbac.PermCompute*
		// registry so the policy evaluator can answer with the caller's
		// role grant (tenant.viewer / member / admin / owner).
		case isComputeInstanceVNCPath(path) && method == "GET":
			// WS-24: noVNC graphical console. Distinct permission from
			// exec — only granted to tenant.admin + tenant.member.
			return middleware.RequirePerm(policy, rbac.PermComputeInstanceConsoleVNC)(c)
		case isComputeInstanceExecPath(path) && method == "POST":
			// exec needs a running instance; reuse the start permission
			// since both involve "interact with a running instance".
			return middleware.RequirePerm(policy, rbac.PermComputeInstanceStart)(c)
		case isComputeSnapshotRestorePath(path) && method == "POST":
			// WS-25: restore replaces instance state wholesale; requires
			// the higher instance.update perm.
			return middleware.RequirePerm(policy, rbac.PermComputeInstanceUpdate)(c)
		case isComputeSnapshotPath(path) && method == "POST":
			// WS-25: snapshot create / take.
			return middleware.RequirePerm(policy, rbac.PermComputeSnapshotCreate)(c)
		case isComputeSnapshotPath(path) && method == "GET":
			return middleware.RequirePerm(policy, rbac.PermComputeSnapshotRead)(c)
		case isComputeSnapshotPath(path) && method == "DELETE":
			return middleware.RequirePerm(policy, rbac.PermComputeSnapshotDelete)(c)
		case isComputeSnapshotPolicyPath(path) && method == "POST":
			return middleware.RequirePerm(policy, rbac.PermComputeSnapshotPolicyCreate)(c)
		case isComputeSnapshotPolicyPath(path) && method == "GET":
			return middleware.RequirePerm(policy, rbac.PermComputeSnapshotPolicyRead)(c)
		case isComputeSnapshotPolicyPath(path) && method == "PATCH":
			return middleware.RequirePerm(policy, rbac.PermComputeSnapshotPolicyUpdate)(c)
		case isComputeSnapshotPolicyPath(path) && method == "DELETE":
			return middleware.RequirePerm(policy, rbac.PermComputeSnapshotPolicyDelete)(c)
		case isComputeBackupTargetPath(path) && method == "POST":
			return middleware.RequirePerm(policy, rbac.PermComputeBackupTargetCreate)(c)
		case isComputeBackupTargetPath(path) && method == "GET":
			return middleware.RequirePerm(policy, rbac.PermComputeBackupTargetRead)(c)
		case isComputeBackupTargetPath(path) && method == "DELETE":
			return middleware.RequirePerm(policy, rbac.PermComputeBackupTargetDelete)(c)
		case isComputeBackupPath(path) && method == "GET":
			return middleware.RequirePerm(policy, rbac.PermComputeBackupRead)(c)
		case isComputeBackupPath(path) && method == "DELETE":
			return middleware.RequirePerm(policy, rbac.PermComputeBackupDelete)(c)
		case isComputeInstanceBackupsPath(path) && method == "GET":
			// WS-25: per-instance backup listing. Reuses the snapshot
			// read perm so tenant.viewer can see backups alongside snapshots.
			return middleware.RequirePerm(policy, rbac.PermComputeBackupRead)(c)
		case isComputeInstanceLifecyclePath(path) && method == "POST":
			return middleware.RequirePerm(policy, computeInstanceActionPerm(path))(c)
		case isComputeInstancePath(path) && method == "POST":
			return middleware.RequirePerm(policy, rbac.PermComputeInstanceCreate)(c)
		case isComputeInstancePath(path) && method == "GET":
			return middleware.RequirePerm(policy, rbac.PermComputeInstanceRead)(c)
		case isComputeInstancePath(path) && method == "PATCH":
			return middleware.RequirePerm(policy, rbac.PermComputeInstanceUpdate)(c)
		case isComputeInstancePath(path) && method == "DELETE":
			return middleware.RequirePerm(policy, rbac.PermComputeInstanceDelete)(c)
		case isComputeImagePath(path) && method == "POST":
			return middleware.RequirePerm(policy, rbac.PermComputeInstanceCreate)(c)
		case isComputeImagePath(path) && method == "GET":
			return middleware.RequirePerm(policy, rbac.PermComputeImageRead)(c)
		case isComputeImagePath(path) && method == "DELETE":
			return middleware.RequirePerm(policy, rbac.PermComputeInstanceDelete)(c)
		case isComputeProfilePath(path) && method == "POST":
			return middleware.RequirePerm(policy, rbac.PermComputeProfileApply)(c)
		case isComputeProfilePath(path) && method == "GET":
			return middleware.RequirePerm(policy, rbac.PermComputeProfileRead)(c)
		case isComputeProfilePath(path) && method == "DELETE":
			return middleware.RequirePerm(policy, rbac.PermComputeProfileApply)(c)
		case isComputeNetworkPath(path) && method == "POST":
			return middleware.RequirePerm(policy, rbac.PermComputeNetworkCreate)(c)
		case isComputeNetworkPath(path) && method == "GET":
			return middleware.RequirePerm(policy, rbac.PermComputeNetworkRead)(c)
		case isComputeNetworkPath(path) && method == "DELETE":
			return middleware.RequirePerm(policy, rbac.PermComputeNetworkCreate)(c)
		case isComputeStoragePath(path) && method == "POST":
			return middleware.RequirePerm(policy, rbac.PermComputeNetworkCreate)(c)
		case isComputeStoragePath(path) && method == "GET":
			return middleware.RequirePerm(policy, rbac.PermComputeStoragePoolRead)(c)
		case isComputeStoragePath(path) && method == "DELETE":
			return middleware.RequirePerm(policy, rbac.PermComputeStoragePoolRead)(c)

		// WS-26: compute cluster admin endpoints. The cluster member
		// list is granted to viewer + member + admin (so the UI panel
		// renders without elevating); evacuate/restore is admin-only;
		// migrate is member + admin (the instance owner can rebalance
		// their own instances). All audit-emitted actions are tracked
		// via the compute.audit.* slugs.
		case isComputeClusterMemberEvacuatePath(path) && method == "POST":
			return middleware.RequirePerm(policy, rbac.PermComputeClusterMemberEvacuate)(c)
		case isComputeClusterMemberPath(path) && method == "GET":
			return middleware.RequirePerm(policy, rbac.PermComputeClusterMemberList)(c)
		case isComputeClusterMembersPath(path) && method == "GET":
			return middleware.RequirePerm(policy, rbac.PermComputeClusterMemberList)(c)
		case isComputeInstanceMigratePath(path) && method == "POST":
			return middleware.RequirePerm(policy, rbac.PermComputeInstanceMigrate)(c)

		// WS-15: DNS module endpoints. Every /api/v1/dns/* path is gated;
		// the slug maps 1:1 with the rbac.PermDNS* registry so the policy
		// evaluator can answer with the caller's role grant
		// (tenant.viewer / member / admin / owner). The DNSSEC toggle +
		// the apply-template path both reuse dns.zone.update so a tenant
		// admin can manage DNSSEC + templates without needing a separate
		// permission.
		case isDNSRecordPath(path) && method == "POST":
			return middleware.RequirePerm(policy, rbac.PermDNSRecordCreate)(c)
		case isDNSRecordPath(path) && method == "GET":
			return middleware.RequirePerm(policy, rbac.PermDNSRecordRead)(c)
		case isDNSRecordPath(path) && method == "PATCH":
			return middleware.RequirePerm(policy, rbac.PermDNSRecordUpdate)(c)
		case isDNSRecordPath(path) && method == "DELETE":
			return middleware.RequirePerm(policy, rbac.PermDNSRecordDelete)(c)
		case isDNSApplyTemplatePath(path) && method == "POST":
			return middleware.RequirePerm(policy, rbac.PermDNSZoneUpdate)(c)
		case isDNSDNSSECPath(path) && method == "POST":
			return middleware.RequirePerm(policy, rbac.PermDNSZoneUpdate)(c)
		case isDNSZonePath(path) && method == "POST":
			return middleware.RequirePerm(policy, rbac.PermDNSZoneCreate)(c)
		case isDNSZonePath(path) && method == "GET":
			return middleware.RequirePerm(policy, rbac.PermDNSZoneRead)(c)
		case isDNSZonePath(path) && method == "PATCH":
			return middleware.RequirePerm(policy, rbac.PermDNSZoneUpdate)(c)
		case isDNSZonePath(path) && method == "DELETE":
			return middleware.RequirePerm(policy, rbac.PermDNSZoneDelete)(c)
		case isDNSTemplatePath(path) && method == "GET":
			return middleware.RequirePerm(policy, rbac.PermDNSZoneRead)(c)

		// WS-28: DNS domain (registrar resale) endpoints. Every
		// /api/v1/dns/domains/* path is gated. The paid endpoints
		// (register / renew / transfer) require their own slug so
		// tenant.viewer (which holds search + read only) cannot
		// accidentally trigger a charge.
		case isDNSDomainRenewPath(path) && method == "POST":
			return middleware.RequirePerm(policy, rbac.PermDNSDomainRenew)(c)
		case isDNSDomainTransferPath(path) && method == "POST":
			return middleware.RequirePerm(policy, rbac.PermDNSDomainTransfer)(c)
		case isDNSDomainSearchPath(path) && method == "POST":
			return middleware.RequirePerm(policy, rbac.PermDNSDomainSearch)(c)
		case isDNSDomainPath(path) && method == "POST":
			return middleware.RequirePerm(policy, rbac.PermDNSDomainRegister)(c)
		case isDNSDomainPath(path) && method == "GET":
			return middleware.RequirePerm(policy, rbac.PermDNSDomainRead)(c)
		case isDNSDomainPath(path) && method == "DELETE":
			return middleware.RequirePerm(policy, rbac.PermDNSDomainDelete)(c)

		// WS-16: storage module endpoints. Every /api/v1/storage/* path
		// is gated; the slug maps 1:1 with the rbac.PermS3* registry so
		// the policy evaluator can answer with the caller's role grant
		// (tenant.viewer / member / admin / owner). The presign path
		// (POST) reuses s3.object.read for both GET + PUT URLs because
		// the Lahijan permission catalog does not split upload vs
		// download today; a future WS may add s3.object.write.
		case isStorageBucketPath(path) && method == "POST":
			return middleware.RequirePerm(policy, rbac.PermS3BucketCreate)(c)
		case isStorageBucketPath(path) && method == "GET":
			return middleware.RequirePerm(policy, rbac.PermS3BucketRead)(c)
		case isStorageBucketPath(path) && method == "PATCH":
			return middleware.RequirePerm(policy, rbac.PermS3BucketUpdate)(c)
		case isStorageBucketPath(path) && method == "DELETE":
			return middleware.RequirePerm(policy, rbac.PermS3BucketDelete)(c)
		case isStorageCredentialsPath(path) && method == "POST":
			return middleware.RequirePerm(policy, rbac.PermS3CredentialsCreate)(c)
		case isStorageCredentialsPath(path) && method == "GET":
			return middleware.RequirePerm(policy, rbac.PermS3BucketRead)(c)
		case isStorageCredentialsPath(path) && method == "DELETE":
			return middleware.RequirePerm(policy, rbac.PermS3CredentialsRevoke)(c)
		case isStoragePresignPath(path) && method == "POST":
			return middleware.RequirePerm(policy, rbac.PermS3ObjectRead)(c)
		case isStorageQuotaPath(path) && method == "POST":
			return middleware.RequirePerm(policy, rbac.PermS3BucketUpdate)(c)
		case isStorageUsagePath(path) && method == "GET":
			return middleware.RequirePerm(policy, rbac.PermS3BucketRead)(c)

		// WS-17: billing & metering endpoints. Every /api/v1/me/*
		// path is the user reading their own data; every
		// /api/v1/admin/billing/* and /api/v1/admin/users/{id}/*
		// path is an admin privileged action.
		case isBillingAdminUserTopupPath(path) && method == "POST":
			return middleware.RequirePerm(policy, rbac.PermBillingBalanceAdjust)(c)
		case isBillingAdminUserRefundPath(path) && method == "POST":
			return middleware.RequirePerm(policy, rbac.PermBillingBalanceAdjust)(c)
		case isBillingAdminUserBalancePath(path) && method == "GET":
			return middleware.RequirePerm(policy, rbac.PermBillingBalanceRead)(c)
		case isBillingAdminUserBalancePath(path) && method == "POST":
			return middleware.RequirePerm(policy, rbac.PermBillingBalanceAdjust)(c)
		case isBillingAdminUserLedgerPath(path) && method == "GET":
			return middleware.RequirePerm(policy, rbac.PermBillingLedgerRead)(c)
		case isBillingAdminPricesPath(path) && method == "POST":
			return middleware.RequirePerm(policy, rbac.PermBillingPriceCatalogUpdate)(c)
		case isBillingAdminPricesPath(path) && method == "GET":
			return middleware.RequirePerm(policy, rbac.PermBillingPriceCatalogRead)(c)
		case isBillingMeBalancePath(path) && method == "GET":
			return middleware.RequirePerm(policy, rbac.PermBillingBalanceRead)(c)
		case isBillingMeUsagePath(path) && method == "GET":
			return middleware.RequirePerm(policy, rbac.PermBillingBalanceRead)(c)
		case isBillingMeLedgerPath(path) && method == "GET":
			return middleware.RequirePerm(policy, rbac.PermBillingLedgerRead)(c)
		case isBillingMeReceiptsPDFPath(path) && method == "GET":
			return middleware.RequirePerm(policy, rbac.PermBillingReceiptRead)(c)
		case isBillingMeReceiptsPath(path) && method == "GET":
			return middleware.RequirePerm(policy, rbac.PermBillingReceiptRead)(c)
		case isBillingMeReceiptsPath(path) && method == "POST":
			return middleware.RequirePerm(policy, rbac.PermBillingReceiptCreate)(c)

		// WS-27: payment gateway endpoints. The user-tree routes
		// (/api/v1/billing/*) require the user-scoped perms; the
		// admin-tree routes (/api/v1/admin/billing/{plans,promo-codes,
		// webhook-events}/*) require the admin perms. The webhook
		// receiver (/api/v1/webhooks/stripe) is UNAUTHENTICATED —
		// signature verification is the auth, and the audit gate
		// bypasses it entirely.
		case isBillingWebhookPath(path) && method == "POST":
			return c.Next()
		case isBillingConfigPath(path) && method == "GET":
			return c.Next()
		case isBillingPublicPlansPath(path) && method == "GET":
			return c.Next()
		case isBillingPaymentMethodsPath(path) && method == "GET":
			return middleware.RequirePerm(policy, rbac.PermBillingPaymentMethodManage)(c)
		case isBillingPaymentMethodsPath(path) && method == "POST":
			return middleware.RequirePerm(policy, rbac.PermBillingPaymentMethodManage)(c)
		case isBillingPaymentMethodPath(path) && method == "DELETE":
			return middleware.RequirePerm(policy, rbac.PermBillingPaymentMethodManage)(c)
		case isBillingTopupPath(path) && method == "POST":
			return middleware.RequirePerm(policy, rbac.PermBillingPaymentIntentCreate)(c)
		case isBillingSubscriptionsPath(path) && method == "GET":
			return middleware.RequirePerm(policy, rbac.PermBillingSubscriptionManage)(c)
		case isBillingSubscriptionsPath(path) && method == "POST":
			return middleware.RequirePerm(policy, rbac.PermBillingSubscriptionManage)(c)
		case isBillingSubscriptionPath(path) && method == "DELETE":
			return middleware.RequirePerm(policy, rbac.PermBillingSubscriptionManage)(c)
		case isBillingRedeemPath(path) && method == "POST":
			return middleware.RequirePerm(policy, rbac.PermBillingPromoCodeRedeem)(c)
		case isBillingAdminPlansPath(path) && method == "GET":
			return middleware.RequirePerm(policy, rbac.PermBillingPlanRead)(c)
		case isBillingAdminPlanPushPath(path) && method == "POST":
			return middleware.RequirePerm(policy, rbac.PermBillingPlanManage)(c)
		case isBillingAdminPlansPath(path) && (method == "POST" || method == "PATCH" || method == "DELETE"):
			return middleware.RequirePerm(policy, rbac.PermBillingPlanManage)(c)
		case isBillingAdminPromoCodesPath(path) && method == "GET":
			return middleware.RequirePerm(policy, rbac.PermBillingPromoCodeManage)(c)
		case isBillingAdminPromoCodesPath(path) && method == "POST":
			return middleware.RequirePerm(policy, rbac.PermBillingPromoCodeManage)(c)
		case isBillingAdminPromoCodeRevokePath(path) && method == "POST":
			return middleware.RequirePerm(policy, rbac.PermBillingPromoCodeManage)(c)
		case isBillingAdminWebhookEventsPath(path) && method == "GET":
			return middleware.RequirePerm(policy, rbac.PermBillingWebhookRead)(c)
		}
		return c.Next()
	}
}

// isComputeInstancePath reports whether path targets the instances
// collection or a specific instance (but not the action sub-paths).
func isComputeInstancePath(path string) bool {
	if path == "/api/v1/compute/instances" {
		return true
	}
	return strings.HasPrefix(path, "/api/v1/compute/instances/") &&
		!isComputeInstanceLifecyclePath(path) &&
		!isComputeInstanceExecPath(path) &&
		!isComputeInstanceVNCPath(path) &&
		!isComputeSnapshotPath(path) &&
		!isComputeSnapshotRestorePath(path) &&
		!isComputeInstanceBackupsPath(path) &&
		!isComputeInstanceMigratePath(path)
}

// isComputeInstanceLifecyclePath reports whether path is one of the
// /instances/{id}/{action} lifecycle endpoints.
func isComputeInstanceLifecyclePath(path string) bool {
	for _, a := range []string{"start", "stop", "restart", "freeze", "unfreeze"} {
		if strings.HasSuffix(path, "/"+a) && strings.HasPrefix(path, "/api/v1/compute/instances/") {
			return true
		}
	}
	return false
}

// isComputeInstanceExecPath reports whether path is the exec endpoint.
func isComputeInstanceExecPath(path string) bool {
	return strings.HasPrefix(path, "/api/v1/compute/instances/") && strings.HasSuffix(path, "/exec")
}

// isComputeInstanceVNCPath reports whether path is the WS-24 noVNC
// WebSocket endpoint. The audit gate dispatches it to
// RequirePerm(compute.instance.console.vnc) so only tenant.admin +
// tenant.member reach the handler.
func isComputeInstanceVNCPath(path string) bool {
	return strings.HasPrefix(path, "/api/v1/compute/instances/") && strings.HasSuffix(path, "/vnc")
}

// -------------------------------------------------------------------------
// WS-25 path helpers
// -------------------------------------------------------------------------

// isComputeSnapshotPath reports whether path targets the snapshots
// collection of an instance or a specific snapshot (but NOT the restore
// sub-path which has its own perm gate).
func isComputeSnapshotPath(path string) bool {
	if !strings.HasPrefix(path, "/api/v1/compute/instances/") {
		return false
	}
	if strings.HasSuffix(path, "/snapshots") {
		return true
	}
	if isComputeSnapshotRestorePath(path) {
		return false
	}
	return strings.Contains(path, "/snapshots/")
}

// isComputeSnapshotRestorePath reports whether path is the snapshot
// restore endpoint (POST /instances/{id}/snapshots/{snap}/restore).
func isComputeSnapshotRestorePath(path string) bool {
	return strings.HasPrefix(path, "/api/v1/compute/instances/") &&
		strings.Contains(path, "/snapshots/") &&
		strings.HasSuffix(path, "/restore")
}

// isComputeInstanceBackupsPath reports whether path is the per-instance
// backups listing endpoint.
func isComputeInstanceBackupsPath(path string) bool {
	return strings.HasPrefix(path, "/api/v1/compute/instances/") &&
		strings.HasSuffix(path, "/backups")
}

// isComputeSnapshotPolicyPath reports whether path targets the
// snapshot-policies collection or a specific policy.
func isComputeSnapshotPolicyPath(path string) bool {
	if path == "/api/v1/compute/snapshot-policies" {
		return true
	}
	return strings.HasPrefix(path, "/api/v1/compute/snapshot-policies/")
}

// isComputeBackupTargetPath reports whether path targets the backup-targets
// collection or a specific target.
func isComputeBackupTargetPath(path string) bool {
	if path == "/api/v1/compute/backup-targets" {
		return true
	}
	return strings.HasPrefix(path, "/api/v1/compute/backup-targets/")
}

// isComputeBackupPath reports whether path targets the backups collection
// or a specific backup.
func isComputeBackupPath(path string) bool {
	if path == "/api/v1/compute/backups" {
		return true
	}
	return strings.HasPrefix(path, "/api/v1/compute/backups/")
}

// isComputeClusterMembersPath reports whether path targets the cluster
// members collection (WS-26).
func isComputeClusterMembersPath(path string) bool {
	return path == "/api/v1/compute/cluster/members"
}

// isComputeClusterMemberPath reports whether path targets a specific
// cluster member (WS-26). Used by both GET (member detail) and POST
// (evacuate/restore) — the audit gate distinguishes by method.
func isComputeClusterMemberPath(path string) bool {
	return strings.HasPrefix(path, "/api/v1/compute/cluster/members/")
}

// isComputeClusterMemberEvacuatePath reports whether path is the
// evacuate/restore sub-resource of a specific member (WS-26). The
// trailing segment is the action ("evacuate" or "restore").
func isComputeClusterMemberEvacuatePath(path string) bool {
	if !strings.HasPrefix(path, "/api/v1/compute/cluster/members/") {
		return false
	}
	return strings.HasSuffix(path, "/evacuate") || strings.HasSuffix(path, "/restore")
}

// isComputeInstanceMigratePath reports whether path targets the
// per-instance migrate endpoint (WS-26).
func isComputeInstanceMigratePath(path string) bool {
	if !strings.HasPrefix(path, "/api/v1/compute/instances/") {
		return false
	}
	return strings.HasSuffix(path, "/migrate")
}

// computeInstanceActionPerm maps the trailing path segment to the matching
// rbac permission slug. Caller MUST ensure path is a lifecycle path.
func computeInstanceActionPerm(path string) string {
	switch {
	case strings.HasSuffix(path, "/start"):
		return rbac.PermComputeInstanceStart
	case strings.HasSuffix(path, "/stop"):
		return rbac.PermComputeInstanceStop
	case strings.HasSuffix(path, "/restart"):
		return rbac.PermComputeInstanceRestart
	case strings.HasSuffix(path, "/freeze"), strings.HasSuffix(path, "/unfreeze"):
		// freeze/unfreeze are state changes; reuse stop (the closest
		// permission in the registry). A future WS can split these.
		return rbac.PermComputeInstanceStop
	}
	return rbac.PermComputeInstanceRead
}

// isComputeImagePath / isComputeProfilePath / isComputeNetworkPath /
// isComputeStoragePath mirror isComputeInstancePath for the secondary
// resources.
func isComputeImagePath(path string) bool {
	if path == "/api/v1/compute/images" {
		return true
	}
	return strings.HasPrefix(path, "/api/v1/compute/images/")
}

func isComputeProfilePath(path string) bool {
	if path == "/api/v1/compute/profiles" {
		return true
	}
	return strings.HasPrefix(path, "/api/v1/compute/profiles/")
}

func isComputeNetworkPath(path string) bool {
	if path == "/api/v1/compute/networks" {
		return true
	}
	return strings.HasPrefix(path, "/api/v1/compute/networks/")
}

func isComputeStoragePath(path string) bool {
	if path == "/api/v1/compute/storage" {
		return true
	}
	return strings.HasPrefix(path, "/api/v1/compute/storage/")
}

// isDNSZonePath reports whether path targets the zones collection or a
// specific zone (but not the records / dnssec / apply-template sub-paths).
func isDNSZonePath(path string) bool {
	if path == "/api/v1/dns/zones" {
		return true
	}
	if !strings.HasPrefix(path, "/api/v1/dns/zones/") {
		return false
	}
	return !isDNSRecordPath(path) &&
		!isDNSApplyTemplatePath(path) &&
		!isDNSDNSSECPath(path)
}

// isDNSRecordPath reports whether path targets the records collection of
// a zone or a specific record within it.
func isDNSRecordPath(path string) bool {
	if !strings.HasPrefix(path, "/api/v1/dns/zones/") {
		return false
	}
	return strings.Contains(path, "/records")
}

// isDNSDNSSECPath reports whether path is the DNSSEC toggle endpoint.
func isDNSDNSSECPath(path string) bool {
	if !strings.HasPrefix(path, "/api/v1/dns/zones/") {
		return false
	}
	return strings.Contains(path, "/dnssec/enable") || strings.Contains(path, "/dnssec/disable")
}

// isDNSApplyTemplatePath reports whether path is the apply-template endpoint.
func isDNSApplyTemplatePath(path string) bool {
	if !strings.HasPrefix(path, "/api/v1/dns/zones/") {
		return false
	}
	return strings.HasSuffix(path, "/apply-template")
}

// isDNSTemplatePath reports whether path targets the read-only templates
// catalog.
func isDNSTemplatePath(path string) bool {
	return path == "/api/v1/dns/templates"
}

// -------------------------------------------------------------------------
// WS-28 DNS domain (registrar resale) path helpers.
// -------------------------------------------------------------------------

// isDNSDomainPath reports whether path targets the domains collection
// or a specific domain (but NOT the renew / search / transfer sub-paths).
func isDNSDomainPath(path string) bool {
	if path == "/api/v1/dns/domains" {
		return true
	}
	if !strings.HasPrefix(path, "/api/v1/dns/domains/") {
		return false
	}
	return !isDNSDomainRenewPath(path)
}

// isDNSDomainSearchPath reports whether path is the search endpoint.
func isDNSDomainSearchPath(path string) bool {
	return path == "/api/v1/dns/domains/search"
}

// isDNSDomainTransferPath reports whether path is the transfer endpoint.
func isDNSDomainTransferPath(path string) bool {
	return path == "/api/v1/dns/domains/transfer"
}

// isDNSDomainRenewPath reports whether path is the per-domain renew
// endpoint (POST /api/v1/dns/domains/{id}/renew).
func isDNSDomainRenewPath(path string) bool {
	if !strings.HasPrefix(path, "/api/v1/dns/domains/") {
		return false
	}
	return strings.HasSuffix(path, "/renew")
}

// isStorageBucketPath reports whether path targets the buckets collection
// or a specific bucket (but not the credentials / presign / quota / usage
// sub-paths). Used by the audit gate so the bucket-level permission
// (s3.bucket.read / create / update / delete) is enforced on every
// bucket-rooted call.
func isStorageBucketPath(path string) bool {
	if path == "/api/v1/storage/buckets" {
		return true
	}
	if !strings.HasPrefix(path, "/api/v1/storage/buckets/") {
		return false
	}
	return !isStorageCredentialsPath(path) &&
		!isStoragePresignPath(path) &&
		!isStorageQuotaPath(path) &&
		!isStorageUsagePath(path)
}

// isStorageCredentialsPath reports whether path targets the credentials
// collection of a bucket or a specific credential within it.
func isStorageCredentialsPath(path string) bool {
	if !strings.HasPrefix(path, "/api/v1/storage/buckets/") {
		return false
	}
	return strings.Contains(path, "/credentials")
}

// isStoragePresignPath reports whether path is the presign endpoint.
func isStoragePresignPath(path string) bool {
	if !strings.HasPrefix(path, "/api/v1/storage/buckets/") {
		return false
	}
	return strings.HasSuffix(path, "/presign")
}

// isStorageQuotaPath reports whether path is the quota endpoint.
func isStorageQuotaPath(path string) bool {
	if !strings.HasPrefix(path, "/api/v1/storage/buckets/") {
		return false
	}
	return strings.HasSuffix(path, "/quota")
}

// isStorageUsagePath reports whether path is the usage endpoint.
func isStorageUsagePath(path string) bool {
	if !strings.HasPrefix(path, "/api/v1/storage/buckets/") {
		return false
	}
	return strings.HasSuffix(path, "/usage")
}

// -------------------------------------------------------------------------
// WS-17 billing path helpers.
//
// The billing surface has three roots:
//
//   * /api/v1/me/{balance, usage, ledger, receipts}*  (user self-service)
//   * /api/v1/admin/billing/prices*                   (admin catalog)
//   * /api/v1/admin/users/{userId}/{topup, refund, ledger, balance}
//
// Each helper matches a specific subtree so the audit gate dispatches
// to the right RequirePerm slug.
// -------------------------------------------------------------------------

// isBillingMeBalancePath reports whether path is GET /api/v1/me/balance.
func isBillingMeBalancePath(path string) bool {
	return path == "/api/v1/me/balance"
}

// isBillingMeUsagePath reports whether path is GET /api/v1/me/usage.
func isBillingMeUsagePath(path string) bool {
	return path == "/api/v1/me/usage"
}

// isBillingMeLedgerPath reports whether path is GET /api/v1/me/ledger.
func isBillingMeLedgerPath(path string) bool {
	return path == "/api/v1/me/ledger"
}

// isBillingMeReceiptsPath reports whether path targets the receipts
// collection (GET list or POST generate). The PDF + single-receipt
// sub-paths are excluded.
func isBillingMeReceiptsPath(path string) bool {
	if path == "/api/v1/me/receipts" {
		return true
	}
	if !strings.HasPrefix(path, "/api/v1/me/receipts/") {
		return false
	}
	return !strings.HasSuffix(path, ".pdf")
}

// isBillingMeReceiptsPDFPath reports whether path is the PDF download
// (GET /api/v1/me/receipts/{receiptId}.pdf).
func isBillingMeReceiptsPDFPath(path string) bool {
	return strings.HasPrefix(path, "/api/v1/me/receipts/") && strings.HasSuffix(path, ".pdf")
}

// isBillingAdminPricesPath reports whether path targets the price
// catalog collection.
func isBillingAdminPricesPath(path string) bool {
	if path == "/api/v1/admin/billing/prices" {
		return true
	}
	return strings.HasPrefix(path, "/api/v1/admin/billing/prices/")
}

// isBillingAdminUserTopupPath reports whether path is the topup endpoint.
func isBillingAdminUserTopupPath(path string) bool {
	return strings.HasPrefix(path, "/api/v1/admin/users/") && strings.HasSuffix(path, "/topup")
}

// isBillingAdminUserRefundPath reports whether path is the refund endpoint.
func isBillingAdminUserRefundPath(path string) bool {
	return strings.HasPrefix(path, "/api/v1/admin/users/") && strings.HasSuffix(path, "/refund")
}

// isBillingAdminUserLedgerPath reports whether path is the user ledger
// listing endpoint.
func isBillingAdminUserLedgerPath(path string) bool {
	return strings.HasPrefix(path, "/api/v1/admin/users/") && strings.HasSuffix(path, "/ledger")
}

// isBillingAdminUserBalancePath reports whether path targets the
// per-user balance (GET read or POST rebuild).
func isBillingAdminUserBalancePath(path string) bool {
	return strings.HasPrefix(path, "/api/v1/admin/users/") && strings.HasSuffix(path, "/balance")
}

// -------------------------------------------------------------------------
// WS-27 payment-gateway path helpers.
//
// The user-tree has four roots:
//   * /api/v1/billing/config                                 (public config)
//   * /api/v1/billing/payment-methods*                       (card cache)
//   * /api/v1/billing/topup                                  (one-shot PI)
//   * /api/v1/billing/subscriptions*                         (recurring)
//   * /api/v1/billing/redeem                                 (promo codes)
//   * /api/v1/billing/plans                                  (public list)
//
// The admin-tree has three roots:
//   * /api/v1/admin/billing/plans* + .../push
//   * /api/v1/admin/billing/promo-codes* + .../revoke
//   * /api/v1/admin/billing/webhook-events
//
// Plus the webhook receiver:
//   * /api/v1/webhooks/stripe                                (no rbac)
// -------------------------------------------------------------------------

func isBillingConfigPath(path string) bool {
	return path == "/api/v1/billing/config"
}

func isBillingPublicPlansPath(path string) bool {
	return path == "/api/v1/billing/plans"
}

func isBillingPaymentMethodsPath(path string) bool {
	return path == "/api/v1/billing/payment-methods"
}

func isBillingPaymentMethodPath(path string) bool {
	return strings.HasPrefix(path, "/api/v1/billing/payment-methods/")
}

func isBillingTopupPath(path string) bool {
	return path == "/api/v1/billing/topup"
}

func isBillingSubscriptionsPath(path string) bool {
	return path == "/api/v1/billing/subscriptions"
}

func isBillingSubscriptionPath(path string) bool {
	return strings.HasPrefix(path, "/api/v1/billing/subscriptions/")
}

func isBillingRedeemPath(path string) bool {
	return path == "/api/v1/billing/redeem"
}

func isBillingAdminPlansPath(path string) bool {
	if path == "/api/v1/admin/billing/plans" {
		return true
	}
	if !strings.HasPrefix(path, "/api/v1/admin/billing/plans/") {
		return false
	}
	return !isBillingAdminPlanPushPath(path)
}

func isBillingAdminPlanPushPath(path string) bool {
	return strings.HasPrefix(path, "/api/v1/admin/billing/plans/") && strings.HasSuffix(path, "/push")
}

func isBillingAdminPromoCodesPath(path string) bool {
	if path == "/api/v1/admin/billing/promo-codes" {
		return true
	}
	return strings.HasPrefix(path, "/api/v1/admin/billing/promo-codes/")
}

func isBillingAdminPromoCodeRevokePath(path string) bool {
	return strings.HasPrefix(path, "/api/v1/admin/billing/promo-codes/") && strings.HasSuffix(path, "/revoke")
}

func isBillingAdminWebhookEventsPath(path string) bool {
	return path == "/api/v1/admin/billing/webhook-events"
}

func isBillingWebhookPath(path string) bool {
	return path == "/api/v1/webhooks/stripe"
}
